import{_ as a,o as s,c as e,a2 as t}from"./chunks/framework.Boholvbs.js";const k=JSON.parse('{"title":"Installation","description":"Install, update, and remove PrioriCode — installer script, binaries, npm, Nix, Docker, and the self-updater.","frontmatter":{"title":"Installation","description":"Install, update, and remove PrioriCode — installer script, binaries, npm, Nix, Docker, and the self-updater."},"headers":[],"relativePath":"getting-started/install.md","filePath":"getting-started/install.md"}'),n={name:"getting-started/install.md"};function l(r,i,h,o,d,p){return s(),e("div",null,[...i[0]||(i[0]=[t(`<p>One binary, no runtime to babysit. PrioriCode ships a native executable for every platform it builds, plus a self-updater that keeps it fresh.</p><h2 id="recommended-the-installer-script" tabindex="-1">Recommended: the installer script <a class="header-anchor" href="#recommended-the-installer-script" aria-label="Permalink to &quot;Recommended: the installer script&quot;">​</a></h2><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group--t-cf" id="tab-eC5pjZG" checked><label data-title="macOS &amp; Linux" for="tab-eC5pjZG">macOS &amp; Linux</label><input type="radio" name="group--t-cf" id="tab-s0uM82A"><label data-title="Windows (PowerShell)" for="tab-s0uM82A">Windows (PowerShell)</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Prioritech-Indonesia-Optima/prioricode/raw/main/install</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">github.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Prioritech</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Indonesia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Optima</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">prioricode</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">raw</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">main</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div></div></div><p>The script detects your OS, architecture, and CPU — it picks the <code>baseline</code> build on x64 machines without AVX2 and the <code>musl</code> build on Alpine — downloads the matching archive from <a href="https://github.com/Prioritech-Indonesia-Optima/prioricode/releases" target="_blank" rel="noreferrer">GitHub Releases</a>, verifies it against <code>SHA256SUMS.txt</code>, and adds the install directory to your shell&#39;s <code>PATH</code> (the line is tagged <code># prioricode</code>, so it&#39;s easy to find and remove later).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Remove PrioriCode versions older than <code>0.1.x</code> before installing.</p></div><h3 id="installer-knobs" tabindex="-1">Installer knobs <a class="header-anchor" href="#installer-knobs" aria-label="Permalink to &quot;Installer knobs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>How</th></tr></thead><tbody><tr><td>Pin a version</td><td><code>install -v 0.1.48</code> or <code>VERSION=v0.1.48 curl … | bash</code>; PowerShell: <code>-Version</code></td></tr><tr><td>Use a pre-downloaded binary</td><td><code>install -b ./path/to/prioricode</code></td></tr><tr><td>Custom install dir</td><td><code>PRIORICODE_INSTALL_DIR=/usr/local/bin</code></td></tr><tr><td>Alternative bin dir</td><td><code>XDG_BIN_DIR=$HOME/.local/bin</code></td></tr><tr><td>Don&#39;t touch PATH</td><td><code>--no-modify-path</code></td></tr><tr><td>Skip clipboard tooling</td><td><code>--no-clipboard</code> / <code>PRIORICODE_NO_CLIPBOARD=1</code></td></tr></tbody></table><p>Install directory priority on macOS/Linux: <code>$PRIORICODE_INSTALL_DIR</code> → <code>$XDG_BIN_DIR</code> → <code>$HOME/bin</code> → <code>$HOME/.prioricode/bin</code>. On Windows: <code>$env:PRIORICODE_INSTALL_DIR</code>, else <code>%USERPROFILE%\\.prioricode\\bin</code>.</p><h2 id="other-ways-to-install" tabindex="-1">Other ways to install <a class="header-anchor" href="#other-ways-to-install" aria-label="Permalink to &quot;Other ways to install&quot;">​</a></h2><h4 id="npm" tabindex="-1">npm <a class="header-anchor" href="#npm" aria-label="Permalink to &quot;npm&quot;">​</a></h4><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prioricode-ai</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    \`\`\`</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    The</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm launcher runs a postinstall script that fetches the platform binary (\`</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode-ai</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\` </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">depends</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> on per-platform packages like \`</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode-linux-x64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`). If \`--ignore-scripts\` blocks the postinstall, run \`node postinstall.mjs\` inside the installed package or reinstall without the flag.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    ::</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> publishing runs in the release pipeline only when registry credentials are configured, so the package can lag a</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">      GitHub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release. If npm 404s, use the installer script — it is always current.</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:::</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#### Nix</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`\`\`</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github:Prioritech-Indonesia-Optima/prioricode</span></span></code></pre></div><p>The repo ships a flake at its root.</p><h4 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h4><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:/workspace&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /workspace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ghcr.io/prioritech-indonesia-optima/prioricode</span></span></code></pre></div><p>Images are tagged per version and per release channel. Mount your project so the agent can see it — and bring credentials with you via environment variables.</p><h4 id="manual-binary" tabindex="-1">Manual binary <a class="header-anchor" href="#manual-binary" aria-label="Permalink to &quot;Manual binary&quot;">​</a></h4><p>Download <code>prioricode-&lt;os&gt;-&lt;arch&gt;[.zip|.tar.gz]</code> straight from the <a href="https://github.com/Prioritech-Indonesia-Optima/prioricode/releases" target="_blank" rel="noreferrer">releases page</a>, unzip, place it anywhere on your <code>PATH</code>. Targets: darwin (arm64, x64, x64-baseline), linux (arm64, x64, x64-baseline, plus <code>-musl</code> variants), windows (arm64, x64, x64-baseline). Check the download against <code>SHA256SUMS.txt</code> in the same release.</p><p>Arch Linux users: the AUR package <code>prioricode-bin</code> tracks releases.</p><h2 id="where-things-live" tabindex="-1">Where things live <a class="header-anchor" href="#where-things-live" aria-label="Permalink to &quot;Where things live&quot;">​</a></h2><p>PrioriCode keeps its state in standard XDG directories (<code>~/.local/share/prioricode</code>, <code>~/.config/prioricode</code>, and friends). The database, logs, plans, and credentials all sit under those roots — see <a href="./../configure/files.html">configuration files</a> for the full map.</p><h2 id="staying-current" tabindex="-1">Staying current <a class="header-anchor" href="#staying-current" aria-label="Permalink to &quot;Staying current&quot;">​</a></h2><p><code>prioricode</code> checks for updates shortly after the TUI starts. Behavior is controlled by the <code>autoupdate</code> config key:</p><table tabindex="0"><thead><tr><th>Value</th><th>Behavior</th></tr></thead><tbody><tr><td><code>true</code> (default)</td><td>Patch releases update silently; minor/major bumps prompt in the TUI footer.</td></tr><tr><td><code>&quot;notify&quot;</code></td><td>Never auto-applies; always asks first.</td></tr><tr><td><code>false</code></td><td>Quiet. Set <code>PRIORICODE_DISABLE_AUTOUPDATE=1</code> for the same effect with extra steps.</td></tr></tbody></table><p>Only patch versions auto-apply — a minor or major bump is your decision, because those can change behavior.</p><h2 id="upgrading-and-downgrading-by-hand" tabindex="-1">Upgrading and downgrading by hand <a class="header-anchor" href="#upgrading-and-downgrading-by-hand" aria-label="Permalink to &quot;Upgrading and downgrading by hand&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # latest</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.1.48</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # or v0.1.48 — exact pin</span></span></code></pre></div><p>The updater detects how you installed (curl, npm, pnpm, bun, yarn, Homebrew, Scoop, Chocolatey) and uses the same mechanism; override with <code>--method curl|npm|pnpm|bun|brew|choco|scoop</code>. After a script-based upgrade it verifies <code>prioricode --version</code> actually reports the target before declaring victory. Re-running the installer with <code>-v</code> does the same job from scratch.</p><h2 id="uninstalling" tabindex="-1">Uninstalling <a class="header-anchor" href="#uninstalling" aria-label="Permalink to &quot;Uninstalling&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # interactive; confirm each step</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # see what would happen, change nothing</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --keep-config</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # nuke data, keep prioricode.json</span></span></code></pre></div><p>The command removes the app directories (data, cache, config, state — opt out per-family with <code>--keep-config</code> / <code>--keep-data</code>), cleans the <code># prioricode</code> PATH lines it added to your shell rc files, and uninstalls via whichever package manager owns the binary. If you installed a raw binary by hand, delete it yourself.</p><h2 id="shell-completion" tabindex="-1">Shell completion <a class="header-anchor" href="#shell-completion" aria-label="Permalink to &quot;Shell completion&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> completion</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/share/bash-completion/completions/prioricode</span></span></code></pre></div><p>Prints a completion script for your shell (<code>$SHELL</code>). Redirect it wherever your shell looks — zsh, bash, and fish all take a file.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./providers.html">Providers &amp; models</a> — Next step after install: teach PrioriCode which AI to talk to. <ul><li><a href="./../quickstart.html">Quickstart</a> — The two-minute tour of the whole setup.</li><li><a href="./../configure/files.html">Config files</a> — Where <code>prioricode.json</code> is found and how files merge.</li><li><a href="./../reference/cli.html">CLI reference</a> — Every command and flag, one table.</li></ul></li></ul>`,35)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
